// Original — Frictionborn Motion MeshGradient WebGL2 renderer
"use client";

import { useEffect, useRef, useCallback } from "react";
import { createSurface, type Surface } from "@frictionborn/runtime/gl";
import { useFrame, useFrameGuard, usePaused } from "@frictionborn/runtime";
import { vertexShaderSource, fragmentShaderSource } from "./mesh-gradient.glsl";

export interface MeshGradientGLProps {
  colors: [
    [number, number, number],
    [number, number, number],
    [number, number, number],
    [number, number, number]
  ];
  speed?: number;
  distortion?: number;
  swirl?: number;
  grainMixer?: number;
  grainOverlay?: number;
  tier?: number;
  paused?: boolean;
  reducedMotion?: boolean;
  suspended?: boolean;
  onDowngrade?: () => void;
  onContextLost?: () => void;
  onContextRestored?: () => void;
}

export default function MeshGradientGL({
  colors,
  speed = 0.35,
  distortion = 0.5,
  swirl = 0.25,
  grainMixer = 0.08,
  grainOverlay = 0.04,
  tier = 3,
  paused = false,
  reducedMotion = false,
  suspended = false,
  onDowngrade,
  onContextLost,
  onContextRestored,
}: MeshGradientGLProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const glSurface = useRef<Surface | null>(null);
  const glProgram = useRef<WebGLProgram | null>(null);
  const uniformMap = useRef<Map<string, WebGLUniformLocation>>(new Map());

  const elapsedClock = useRef(0);
  const activePalette = useRef(colors);
  const lostHandler = useRef(onContextLost);
  const restoredHandler = useRef(onContextRestored);

  useEffect(() => {
    activePalette.current = colors;
    lostHandler.current = onContextLost;
    restoredHandler.current = onContextRestored;
  });

  const isGlobalPaused = usePaused();

  useFrameGuard({
    onDowngrade: onDowngrade ?? (() => {}),
    active: !paused && !isGlobalPaused && !reducedMotion && !suspended,
  }); // @frictionborn-guard

  const maxDpr = tier >= 3 ? 2.0 : 1.5;
  const meshScale = tier >= 3 ? 1.0 : 0.75;
  const meshOctaves = tier >= 3 ? 4 : 2;

  const flushMeshState = useCallback(
    (timeValue: number) => {
      const surface = glSurface.current;
      const prog = glProgram.current;
      if (!surface || !prog) return;

      const gl = surface.gl;
      const u = uniformMap.current;
      gl.useProgram(prog);

      const uRes = u.get("u_resolution");
      if (uRes) gl.uniform2f(uRes, gl.drawingBufferWidth, gl.drawingBufferHeight);

      const uTime = u.get("u_time");
      if (uTime) gl.uniform1f(uTime, timeValue);

      const uSpeed = u.get("u_speed");
      if (uSpeed) gl.uniform1f(uSpeed, speed * 0.35);

      const uDistort = u.get("u_distortion");
      if (uDistort) gl.uniform1f(uDistort, distortion);

      const uSwirl = u.get("u_swirl");
      if (uSwirl) gl.uniform1f(uSwirl, swirl);

      const uMixer = u.get("u_grain_mixer");
      if (uMixer) gl.uniform1f(uMixer, grainMixer);

      const uOverlay = u.get("u_grain_overlay");
      if (uOverlay) gl.uniform1f(uOverlay, grainOverlay);

      const uOct = u.get("u_octaves");
      if (uOct) gl.uniform1i(uOct, meshOctaves);

      const pal = activePalette.current;
      for (let i = 0; i < 4; i++) {
        const uCol = u.get(`u_color${i}`);
        if (uCol) {
          gl.uniform3f(uCol, pal[i][0], pal[i][1], pal[i][2]);
        }
      }

      surface.draw();
    },
    [speed, distortion, swirl, grainMixer, grainOverlay, meshOctaves]
  );

  useEffect(() => {
    const parent = hostRef.current;
    if (!parent) return;

    const cvs = document.createElement("canvas");
    cvs.setAttribute("aria-hidden", "true");
    cvs.setAttribute("data-frictionborn-gl", "mesh-gradient");
    Object.assign(cvs.style, {
      position: "absolute",
      inset: "0",
      width: "100%",
      height: "100%",
      display: "block",
      pointerEvents: "none",
      zIndex: "2",
    });
    parent.appendChild(cvs);

    const initShaders = (s: Surface) => {
      const gl = s.gl;
      const prog = s.createProgram(vertexShaderSource, fragmentShaderSource);
      glProgram.current = prog;

      const map = new Map<string, WebGLUniformLocation>();
      const names = [
        "u_resolution",
        "u_time",
        "u_speed",
        "u_distortion",
        "u_swirl",
        "u_grain_mixer",
        "u_grain_overlay",
        "u_octaves",
        "u_color0",
        "u_color1",
        "u_color2",
        "u_color3",
      ];
      for (const name of names) {
        const loc = gl.getUniformLocation(prog, name);
        if (loc) map.set(name, loc);
      }
      uniformMap.current = map;
    };

    try {
      const surface = createSurface(cvs, {
        maxDpr,
        scale: meshScale,
        onContextLost: () => {
          cvs.style.display = "none";
          lostHandler.current?.();
        },
        onContextRestored: () => {
          cvs.style.display = "block";
          if (glSurface.current) {
            glSurface.current.resize();
            initShaders(glSurface.current);
            flushMeshState(elapsedClock.current);
          }
          restoredHandler.current?.();
        },
      }); // @frictionborn-guard

      glSurface.current = surface;
      initShaders(surface);
      flushMeshState(elapsedClock.current);
    } catch (failure) {
      console.warn("MeshGradient WebGL2 surface failure", failure);
      if (glSurface.current) {
        glSurface.current.dispose(); // @frictionborn-guard
        glSurface.current = null;
      }
      lostHandler.current?.();
    }

    return () => {
      if (glSurface.current) {
        glSurface.current.dispose(); // @frictionborn-guard
        glSurface.current = null;
      }
      cvs.remove();
    };
  }, [maxDpr, meshScale, flushMeshState]);

  useFrame(
    ({ dt }) => {
      elapsedClock.current += (dt * 0.001) * speed;
      flushMeshState(elapsedClock.current);
    },
    { active: !paused && !isGlobalPaused && !reducedMotion && !suspended } // @frictionborn-guard
  );

  return (
    <div
      ref={hostRef}
      aria-hidden="true"
      className="fb-mesh-surface"
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: 2,
        visibility: suspended ? "hidden" : "visible",
      }}
    />
  );
}

// Source: https://github.com/stegu/webgl-noise — MIT — Copyright (C) 2011 Ashima Arts, Stefan Gustavson
// Adaptation & composition: Original — Frictionborn Motion

export const vertexShaderSource = `#version 300 es
in vec2 position;
out vec2 v_uv;

void main() {
  v_uv = (position + 1.0) * 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const fragmentShaderSource = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2 u_resolution;
uniform float u_time;
uniform float u_speed;
uniform float u_distortion;
uniform float u_swirl;
uniform float u_grain_mixer;
uniform float u_grain_overlay;
uniform int u_octaves;

uniform vec3 u_color0;
uniform vec3 u_color1;
uniform vec3 u_color2;
uniform vec3 u_color3;

// --- Stefan Gustavson / Ashima Arts 2D Simplex Noise (MIT License) ---
vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x * 34.0) + 1.0) * x);
}

float snoise(vec2 v) {
  const vec4 C = vec4(
    0.211324865405187,   // (3.0 - sqrt(3.0)) / 6.0
    0.366025403784439,   // 0.5 * (sqrt(3.0) - 1.0)
   -0.577350269189626,   // -1.0 + 2.0 * C.x
    0.024390243902439    // 1.0 / 41.0
  );

  vec2 i  = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);

  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

  i = mod289(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);

  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}
// --- End simplex noise primitive ---

// Original Frictionborn organic mesh-gradient composition
void main() {
  vec2 p = v_uv;

  // 1. Swirl distortion around center
  vec2 center = vec2(0.5, 0.5);
  vec2 d = p - center;
  float r = length(d);
  float theta = atan(d.y, d.x);
  float swirlEffect = u_swirl * sin(r * 4.0 - u_time * 0.4);
  vec2 pSwirl = center + vec2(cos(theta + swirlEffect), sin(theta + swirlEffect)) * r;

  // 2. Domain-warping with simplex noise
  vec2 warp = vec2(
    snoise(pSwirl * 2.2 + vec2(u_time * 0.15, -u_time * 0.10)),
    snoise(pSwirl * 2.2 + vec2(-u_time * 0.12, u_time * 0.18))
  );
  vec2 pWarped = pSwirl + warp * (u_distortion * 0.28);

  if (u_octaves >= 3) {
    vec2 warpFine = vec2(
      snoise(pWarped * 4.4 + vec2(-u_time * 0.20, u_time * 0.25)),
      snoise(pWarped * 4.4 + vec2(u_time * 0.22, -u_time * 0.15))
    );
    pWarped += warpFine * (u_distortion * 0.12);
  }

  // 3. Dynamic color anchor centers (matching CSS poster positions at rest)
  vec2 a1 = vec2(0.20, 0.30) + vec2(0.08 * sin(u_time * 0.35), 0.06 * cos(u_time * 0.45));
  vec2 a2 = vec2(0.80, 0.70) + vec2(0.07 * cos(u_time * 0.40), 0.08 * sin(u_time * 0.30));
  vec2 a3 = vec2(0.50, 0.50) + vec2(0.06 * sin(u_time * 0.50), 0.07 * cos(u_time * 0.35));

  // 4. Weight interpolation
  float d1 = distance(pWarped, a1);
  float w1 = smoothstep(0.65, 0.0, d1) * 0.75;

  float d2 = distance(pWarped, a2);
  float w2 = smoothstep(0.60, 0.0, d2) * 0.70;

  float d3 = distance(pWarped, a3);
  float w3 = smoothstep(0.70, 0.0, d3) * 0.80;

  // 5. Blending with base color
  vec3 col = u_color0;
  col = mix(col, u_color1, w1);
  col = mix(col, u_color2, w2);
  col = mix(col, u_color3, w3);

  // 6. Subtle grain overlay / dither to eliminate banding
  float noise = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  float grain = noise * (u_grain_mixer * 0.3 + u_grain_overlay * 0.7);
  col += grain;

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
`;

// Original — Frictionborn Motion MeshGradient
"use client";

import React, { useState, useEffect, useRef, useCallback, useId, Suspense, lazy, useImperativeHandle } from "react";
import {
  useCapability,
  useHydrated,
  useReducedMotion,
  useInView,
  resolveCssColor,
  glBudget,
  type Lease,
} from "@frictionborn/runtime";

const MeshGradientGL = lazy(() => import("./mesh-gradient.gl"));

export interface MeshGradientProps extends React.HTMLAttributes<HTMLDivElement> {
  colors?: string[];
  speed?: number;
  distortion?: number;
  swirl?: number;
  grainMixer?: number;
  grainOverlay?: number;
  scrim?: boolean;
  paused?: boolean;
  maxTier?: number;
  reducedMotion?: boolean;
  ref?: React.Ref<HTMLDivElement>;
  children?: React.ReactNode;
}

// Host tokens with CSS system-colour fallbacks; stable module-level constant
const DEFAULT_MESH_TOKENS = [
  "var(--background, Canvas)",
  "var(--primary, CanvasText)",
  "var(--chart-1, var(--accent, GrayText))",
  "var(--chart-2, var(--muted, ButtonFace))",
];

type RgbTriple = [number, number, number];
const DEFAULT_RGB_QUAD: [RgbTriple, RgbTriple, RgbTriple, RgbTriple] = [
  [0.05, 0.06, 0.08],
  [0.22, 0.74, 0.97],
  [0.51, 0.55, 0.97],
  [0.12, 0.16, 0.23],
];

export function MeshGradient({
  colors = DEFAULT_MESH_TOKENS,
  speed = 1.0,
  distortion = 0.5,
  swirl = 0.25,
  grainMixer = 0.08,
  grainOverlay = 0.04,
  scrim = false,
  paused = false,
  maxTier = 3,
  reducedMotion: propReduced,
  ref,
  className = "",
  style,
  children,
  ...props
}: MeshGradientProps) {
  const hostElementRef = useRef<HTMLDivElement | null>(null);
  const uid = useId();
  const isClientHydrated = useHydrated(); // @frictionborn-guard
  const runtimeCap = useCapability(); // @frictionborn-guard
  const prefersReduce = useReducedMotion(); // @frictionborn-guard
  const suppressMotion = propReduced !== undefined ? propReduced : prefersReduce; // @frictionborn-guard
  const isInViewport = useInView(hostElementRef); // @frictionborn-guard

  const [hasContextLease, setHasContextLease] = useState(false);
  const leaseHandle = useRef<Lease | null>(null);
  const instanceTag = useRef(`mesh-${uid}`);
  const [contextSevered, setContextSevered] = useState(false);

  const [downgrades, setDowngrades] = useState(0);
  const effectiveTier = isClientHydrated
    ? Math.max(0, Math.min(runtimeCap.tier, maxTier) - downgrades)
    : 0;
  const [activeColors, setActiveColors] = useState<[RgbTriple, RgbTriple, RgbTriple, RgbTriple]>(DEFAULT_RGB_QUAD);

  const refreshColors = useCallback(() => {
    const el = hostElementRef.current;
    const resolved: RgbTriple[] = colors.map((c) => {
      const rgb = resolveCssColor(el, c);
      return rgb ? (rgb as RgbTriple) : [0.5, 0.5, 0.5];
    });

    const c0 = resolved[0] ?? DEFAULT_RGB_QUAD[0];
    const c1 = resolved[1] ?? resolved[0] ?? DEFAULT_RGB_QUAD[1];
    const c2 = resolved[2] ?? resolved[1] ?? DEFAULT_RGB_QUAD[2];
    const c3 = resolved[3] ?? resolved[0] ?? DEFAULT_RGB_QUAD[3];
    const next: [RgbTriple, RgbTriple, RgbTriple, RgbTriple] = [c0, c1, c2, c3];

    setActiveColors((prev) => {
      const isIdentical =
        prev.length === 4 &&
        prev.every(
          (tuple, i) =>
            Math.abs(tuple[0] - next[i][0]) < 0.002 &&
            Math.abs(tuple[1] - next[i][1]) < 0.002 &&
            Math.abs(tuple[2] - next[i][2]) < 0.002
        );
      return isIdentical ? prev : next;
    });
  }, [colors]);

  useEffect(() => {
    refreshColors();
    if (typeof MutationObserver === "undefined") return;
    const obs = new MutationObserver(refreshColors);
    obs.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme", "data-mode", "style"],
    });
    return () => obs.disconnect();
  }, [refreshColors]);

  // Context lease lifecycle management (Decision 19: reduced motion = no WebGL)
  const isQualifiedForWebGL =
    isClientHydrated && isInViewport && effectiveTier >= 2 && !suppressMotion;

  useEffect(() => {
    if (!isQualifiedForWebGL) {
      if (leaseHandle.current) {
        leaseHandle.current.release(); // @frictionborn-guard
        leaseHandle.current = null;
        setHasContextLease(false);
      }
      return;
    }

    const tryAcquire = () => {
      if (leaseHandle.current) return;
      const acquired = glBudget.acquire({
        id: instanceTag.current,
        priority: 1,
        onEvict: () => {
          leaseHandle.current = null;
          setHasContextLease(false);
        },
      }); // @frictionborn-guard

      if (acquired) {
        leaseHandle.current = acquired;
        setHasContextLease(true);
        // A new lease means a new GL instance: a loss that was never restored must not leave it suspended (same fix as NoiseField, 5c74d38)
        setContextSevered(false);
      }
    };

    tryAcquire();

    const unsubscribe = typeof glBudget.subscribe === "function"
      ? glBudget.subscribe(() => {
          if (!leaseHandle.current) {
            tryAcquire();
          }
        })
      : () => {};

    return () => {
      unsubscribe();
    };
  }, [isQualifiedForWebGL]);

  useEffect(() => {
    return () => {
      leaseHandle.current?.release(); // @frictionborn-guard
      leaseHandle.current = null;
    };
  }, []);

  const handleStepDown = useCallback(() => {
    setDowngrades((prev) => prev + 1); // @frictionborn-guard
  }, []);

  const handleContextLost = useCallback(() => {
    setContextSevered(true); // @frictionborn-guard
  }, []);

  const handleContextRestored = useCallback(() => {
    setContextSevered(false); // @frictionborn-guard
  }, []);

  // Pure CSS poster matching the shader's anchor positions and spatial weighting
  const bgBase = colors[0];
  const posterArt = `radial-gradient(circle at 20% 30%, color-mix(in srgb, ${colors[1] ?? colors[0]} 38%, transparent) 0%, transparent 65%), radial-gradient(circle at 80% 70%, color-mix(in srgb, ${colors[2] ?? colors[0]} 34%, transparent) 0%, transparent 60%), radial-gradient(circle at 50% 50%, color-mix(in srgb, ${colors[3] ?? colors[0]} 40%, transparent) 0%, transparent 70%), ${bgBase}`;

  const renderWebGLMesh = hasContextLease && !suppressMotion && effectiveTier >= 2;

  useImperativeHandle(ref, () => hostElementRef.current as HTMLDivElement);

  return (
    <div
      ref={hostElementRef}
      data-frictionborn-item="mesh-gradient"
      data-tier={effectiveTier}
      className={`fb-mesh-gradient ${className}`}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        minHeight: "260px",
        overflow: "hidden",
        backgroundColor: bgBase,
        ...style,
      }}
      {...props}
    >
      {/* 1. Server-rendered CSS gradient poster always present as fallback (CLS 0) */}
      <div
        data-frictionborn-poster="true"
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          background: posterArt,
          pointerEvents: "none",
        }}
      />

      {/* 2. WebGL canvas rendered client-side only when lease granted and not reduced-motion */}
      {renderWebGLMesh && (
        <Suspense fallback={null}>
          <MeshGradientGL
            suspended={contextSevered}
            colors={activeColors}
            speed={speed}
            distortion={distortion}
            swirl={swirl}
            grainMixer={grainMixer}
            grainOverlay={grainOverlay}
            tier={effectiveTier}
            paused={paused}
            reducedMotion={suppressMotion}
            onDowngrade={handleStepDown}
            onContextLost={handleContextLost}
            onContextRestored={handleContextRestored}
          />
        </Suspense>
      )}

      {/* 3. Theme-aware scrim preserving WCAG AA contrast >= 4.5:1 for overlaid text */}
      {scrim && (
        <div
          aria-hidden="true"
          style={{
            position: "absolute",
            inset: 0,
            background: `radial-gradient(circle at center, color-mix(in srgb, ${bgBase} 20%, transparent) 0%, color-mix(in srgb, ${bgBase} 80%, transparent) 100%)`,
            pointerEvents: "none",
            zIndex: 2,
          }}
        />
      )}

      {/* 4. Children slot */}
      {children && (
        <div
          style={{
            position: "relative",
            zIndex: 3,
            width: "100%",
            height: "100%",
          }}
        >
          {children}
        </div>
      )}
    </div>
  );
}

export default MeshGradient;

